@section('content')<section class="max-w-6xl mx-auto px-5 py-12"><h1 class="text-4xl font-black">Panel <span class="text-orange-500">Mekanik.</span></h1><p class="muted mt-2">Hanya pesanan yang ditugaskan kepada akun kamu yang tampil di sini.</p><div class="space-y-4 mt-8">@forelse($orders as $order)<article class="panel p-6"><div class="flex flex-col md:flex-row justify-between gap-4"><div><p class="link text-xs font-bold">{{ $order->order_number }}</p><h2 class="text-xl font-black mt-1">{{ $order->user->name }} · {{ $order->vehicle?->name }}</h2><p class="muted text-sm mt-2">{{ $order->address ?: 'In-Shop' }}</p><p class="text-sm mt-2">{{ $order->items->pluck('item_name')->join(', ') }}</p></div><div class="md:text-right"><p class="font-bold">{{ str_replace('_',' ',$order->status) }}</p><p class="muted text-sm">Rp{{ number_format($order->total,0,',','.') }}</p></div></div><div class="grid lg:grid-cols-[1fr_auto] gap-4 mt-5"><form method="POST" action="{{ route('mechanic.orders.status',$order) }}" class="grid sm:grid-cols-[1fr_1fr_auto] gap-3">@csrf @method('PATCH')<select class="field" name="status">@foreach(['mechanic_on_the_way','in_service','completed'] as $status)<option value="{{ $status }}" @selected($order->status===$status)>{{ str_replace('_',' ',$status) }}</option>@endforeach</select><input class="field" name="mechanic_notes" value="{{ $order->mechanic_notes }}" placeholder="Catatan pekerjaan"><button class="btn">Update</button></form><button class="rounded-xl border border-slate-600 px-4 py-3 font-bold" onclick="sendLocation({{ $order->id }}, this)">Kirim lokasi GPS</button></div><p id="gps-{{ $order->id }}" class="muted text-xs mt-2"></p></article>@empty<div class="panel p-8 text-center muted">Belum ada pesanan yang ditugaskan.</div>@endforelse</div><div class="mt-6">{{ $orders->links() }}</div></section>@endsection
@push('scripts')<script>async function sendLocation(id,button){const out=document.getElementById('gps-'+id);if(!navigator.geolocation){out.textContent='Browser tidak mendukung GPS.';return;}out.textContent='Meminta izin lokasi…';navigator.geolocation.getCurrentPosition(async p=>{try{const r=await fetch('/mekanik/pesanan/'+id+'/lokasi',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':@json(csrf_token())},body:JSON.stringify({latitude:p.coords.latitude,longitude:p.coords.longitude})});out.textContent=r.ok?'Lokasi GPS berhasil dikirim.':'Gagal mengirim lokasi. Periksa penugasan atau login.';}catch(e){out.textContent='Koneksi gagal.';}},()=>out.textContent='GPS tidak tersedia atau izin ditolak.',{enableHighAccuracy:true,timeout:10000});}</script>@endpush
